import os
import subprocess

import yaml

from hran_admin_cli.exceptions import AdminCLINotSetUpException
from hran_admin_cli.script import AdminCLIScript


class hran_admin_cli(object):
    """
    hran_admin_cli class is used to download ADMIN CLI and execute commands with it.
    """

    def __init__(self):
        self.admin_cli = AdminCLIScript()
        self.admin_cli_dir = None
        self.mplane = None
        self.api_key = None
        self.user = None
        self.password = None
        self.port = None
        self.format = None
        self._basename = None

    @property
    def basename(self):
        return self._basename

    @basename.setter
    def basename(self, basename):
        trunk_prefix = "SBTS00_"
        _, version = basename.split('_', 1)
        if "9999" in version:
            basename = trunk_prefix + version
        if version.endswith(('T1', 'T2')):
            basename = basename.replace("T1", "").replace("T2", "").rstrip('_')
        self._basename = basename

    def setup_admin_cli(
        self, basename, mplane, api_key=None, user="Nemuadmin", password="nemuuser", port="443", output_format="human"
    ):
        """
        Set up hran_admin_cli library and ADMIN CLI environment

        | **Author:** jaroslaw.piszczala@nokia.com
        | **Maintainer:** jaroslaw.piszczala@nokia.com
        | **Released with version:** 1.0

        | **Full description:**
        | Check if ADMIN CLI matching active software version exists in
        | /home/ute/btsauto/ADMIN_CLI. If not, it will be downloaded from WFT.

        **Input Parameters:**

        +------------------+--------+------------------------------------------+
        | Input Parameters | Man.   | Description                              |
        +====================+========+========================================+
        | basename         | Yes    | Active software basename                 |
        +------------------+--------+------------------------------------------+
        | mplane           | Yes    | BTS MPLANE IP                            |
        +------------------+--------+------------------------------------------+
        | api_key          | No     | API KEY for access to artifactory        |
        +------------------+--------+------------------------------------------+
        | user             | No     | BTS Admin username, default='Nemuadmin'  |
        +------------------+--------+------------------------------------------+
        | password         | No     | BTS Admin password, default='nemuuser'   |
        +------------------+--------+------------------------------------------+
        | port             | No     | BTS Admin port, default='443'            |
        +------------------+--------+------------------------------------------+
        | output_format    | No     | Output format, default='human'           |
        +------------------+--------+------------------------------------------+

        **Example of simple usage:**

          .. code-block:: robotframework

            Setup Admin CLI  ${active SW version}  ${MPLANE_IP}


        """
        self.mplane = mplane
        self.api_key = api_key
        self.user = user
        self.password = password
        self.port = port
        self.format = output_format
        self.basename = basename
        self.admin_cli_dir = self.admin_cli.get_admin_cli(self.basename, self.api_key)
        return self.admin_cli_dir

    def send_admin_cli_request(self, request_data, output_file=None, return_value=None, input_file=None,
                               output_json=None):
        """
        Send request via Admin CLI and return dictionary with CLI output.

        | **Author:** artur.juszczak@nokia.com
        | **Maintainer:** jaroslaw.piszczala@nokia.com
        | **Released with version:** 1.0

        | **Full description:**
        | Send request in json format via Admin CLI
        | Use output_file argument if you want to redirect response content
        | to file (useful with RawAlarmHistory request, for example)
        |
        | If you see errorCode:9 and requestMessage:'License not available'
        | you need to change SCF parameter `actCLI` to `true`
        |
        | Available operations/procedures are listed here:
        | http://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs

        **Input Parameters:**

        +--------------------+--------+-------------------------------------+
        | Input Parameters   | Man.   | Description                         |
        +====================+========+=====================================+
        | request_data       | Yes    | Request data in json format         |
        +--------------------+--------+-------------------------------------+
        | output_file        | No     | File path to redirect response to   |
        +--------------------+--------+-------------------------------------+
        | return_value       | No     | Return only value of given key      |
        +--------------------+--------+-------------------------------------+
        | input_file         | No     | File path with input data           |
        +--------------------+--------+-------------------------------------+

        **Example of simple usage:**

          .. code-block:: robotframework

            ${response}=  Send Admin CLI request  {"requestId":100,"parameters":{"name":"getGpsInventoryList"}}

            ${response} == {'errorCode': 0, 'requestStatus': 'completed', 'requestId': 100,
            'requestMessage': {'gnssi': [], 'gnsse': []}, 'time': '1:21:19 PM'}

        **Example with output file:**

          .. code-block:: robotframework

            ${response}=  Send Admin CLI request  {"requestId":100,"parameters":{"name":"getRawAlarmHistory"}}  ${TestFiles}/rah.txt    # noqa

            ${response} == {errorCode': 0, 'outputFileContent': '', 'requestMessage': '',
            'time': '1:13:48 PM', 'requestStatus': 'completed', 'requestId': 100
            'outputFileName': '/home/ute/btsauto/AutoTest/automated/2019-03-07_22-22-26_TEST-CA__TestName/TestFiles/rah.txt'}           # noqa

        | **Return value**
        | Dictionary with CLI output. Default dictionary keys:
        | 'errorCode','requestStatus', 'requestId', 'requestMessage', 'time'
        | For more information, verify your Admin API request in documentation

        """
        self._check_if_admin_cli_exists()

        script_args = [
            "--bts-username={}".format(self.user),
            "--bts-password={}".format(self.password),
            "--debug={}/cli_logs.txt".format(self.admin_cli_dir),
            "--bts-host={}".format(self.mplane),
            "--bts-port={}".format(self.port),
            "--format={}".format(self.format),
            "--data={}".format(request_data),
        ]

        if output_file:
            script_args.append("--output-file={}".format(output_file))
        if input_file:
            script_args.append("--input-file={}".format(input_file))
        if output_json:
            script_args.append("--output-json={}".format(output_json))

        script_path = os.path.join(self.admin_cli_dir, "admin-cli.sh")
        cli = subprocess.Popen([script_path] + script_args, stderr=subprocess.STDOUT, stdout=subprocess.PIPE)
        cli_output = cli.stdout.read()
        parsed_cli_output = yaml.load(cli_output, Loader=yaml.BaseLoader)["CLI LOG"]

        if return_value is None:
            return parsed_cli_output
        else:
            error_msg = "No key in output dict".format(return_value)
            return parsed_cli_output.get(return_value, error_msg)

    def _check_if_admin_cli_exists(self):
        if not self.admin_cli_dir:
            raise AdminCLINotSetUpException("ADMIN_CLI is not available, `setup_admin_cli` before using")
